//! External-BRP acceptance tests over the fetched Bevy showcase fixtures.
//!
//! Fixtures are generated by `scripts/fetch_bevy_examples.sh` and are NOT
//! committed (see `.gitignore`). Each is a real, unmodified Bevy showcase
//! game that serves BRP when `BRP_PORT` is set.
//!
//! ## CI parallelization
//!
//! Set `BEVY_PLAYTEST_FIXTURE=<name>` to restrict the suite to a single
//! fixture. The GitHub Actions matrix runs one job per fixture, each
//! invoking:
//!
//! ```text
//! BEVY_PLAYTEST_FIXTURE=breakout cargo test --test acceptance -- --nocapture
//! ```
//!
//! Unset = run every available fixture (local / monolithic runs).
//!
//! ## Prerequisite
//!
//! Fixtures must be built first (the harness launches the game binary):
//! ```text
//! ./scripts/fetch_bevy_examples.sh
//! cargo build --manifest-path fixtures/<name>/Cargo.toml --bin fixture_<name>
//! ```

//! This test suite requires the `brp` feature: pass `--features brp`
//! (e.g. in CI or locally: `cargo test --features brp --test acceptance`).

#![cfg(feature = "brp")]

use bevy_playtest::brp_runner::{run_scenario_brp, BrpRunConfig};
use bevy_playtest::scenario::Scenario;
use std::path::PathBuf;

/// All fixtures the script knows how to generate, in matrix order.
const ALL_FIXTURES: &[&str] = &[
    "alien_cake_addict",
    "breakout",
    "contributors",
    "desk_toy",
    "game_menu",
    "loading_screen",
    "mines",
];

fn repo_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

/// Fixtures selected for this run: `BEVY_PLAYTEST_FIXTURE` if set (and
/// valid), otherwise every fixture whose generated directory exists.
fn selected_fixtures() -> Vec<String> {
    match std::env::var("BEVY_PLAYTEST_FIXTURE") {
        Ok(name) => {
            assert!(
                ALL_FIXTURES.contains(&name.as_str()),
                "BEVY_PLAYTEST_FIXTURE={name:?} is not a known fixture; \
                 expected one of {ALL_FIXTURES:?}"
            );
            vec![name]
        }
        Err(_) => ALL_FIXTURES
            .iter()
            .filter(|f| repo_root().join("fixtures").join(f).is_dir())
            .map(|f| f.to_string())
            .collect(),
    }
}

/// Path to the built fixture binary, asserting it exists with a hint.
fn fixture_binary(name: &str) -> PathBuf {
    let profile = if cfg!(debug_assertions) {
        "debug"
    } else {
        "release"
    };
    let bin = repo_root()
        .join("target")
        .join(profile)
        .join(format!("fixture_{name}"));
    assert!(
        bin.is_file(),
        "fixture binary not found at {}.\n\
         Generate + build it first:\n\
         \x20 ./scripts/fetch_bevy_examples.sh\n\
         \x20 cargo build --manifest-path fixtures/{name}/Cargo.toml --bin fixture_{name}",
        bin.display()
    );
    bin
}

/// A minimal chaos scenario: drive random inputs for a couple of seconds
/// and assert the world stays finite and alive.
fn chaos_scenario() -> Scenario {
    serde_json::from_str(
        r#"{
            "name": "acceptance-chaos",
            "bot": { "type": "chaos", "seed": 1337 },
            "duration_s": 2.0,
            "tps": 60,
            "invariants": [],
            "setup": {}
        }"#,
    )
    .expect("chaos scenario parses")
}

/// Every selected fixture must boot under BRP, accept injected input for
/// the scenario duration, and terminate without a crash or a non-finite
/// transform.
///
/// Honesty contract: a green run here must mean fixtures actually ran.
/// When fixtures haven't been generated, we fail loudly instead of
/// skipping silently (the "never a vacuous pass" doctrine applies to our
/// own test suite). CI always generates fixtures first; locals who
/// don't want the heavyweight suite can deselect it explicitly
/// (`--exact fixtures_run_under_external_brp --ignore`) or set
/// BEVY_PLAYTEST_FIXTURE.
#[test]
fn fixtures_run_under_external_brp() {
    let fixtures = selected_fixtures();
    assert!(
        !fixtures.is_empty(),
        "no fixtures generated — run ./scripts/fetch_bevy_examples.sh first; \
         refusing to pass vacuously"
    );

    let scenario = chaos_scenario();
    let mut failures: Vec<String> = Vec::new();

    for name in &fixtures {
        let bin = fixture_binary(name);
        let cfg = BrpRunConfig {
            game_binary: bin.to_string_lossy().into_owned(),
            game_args: vec![],
            port: None,
            ..BrpRunConfig::default()
        };

        match run_scenario_brp(&cfg, &scenario) {
            Ok(report) => {
                let viol = serde_json::to_string(&report.violations).unwrap_or_default();
                if report.status != bevy_playtest::enums::PlaytestStatus::Pass {
                    failures.push(format!(
                        "{name}: status {:?}, violations: {viol}",
                        report.status
                    ));
                } else if !report.violations.is_empty() {
                    // Status is Pass, but informational violations surfaced.
                    // Healthy showcases must be CLEAN — an informational hit
                    // (e.g. log_warn, unarmed frozen_world) is a false
                    // positive we want to know about, not swallow.
                    failures.push(format!(
                        "{name}: PASS with non-empty violations (false positives): {viol}"
                    ));
                } else {
                    eprintln!("{name}: ok");
                }
            }
            Err(e) => failures.push(format!("{name}: run error: {e}")),
        }
    }

    assert!(
        failures.is_empty(),
        "external-BRP acceptance failures:\n{}",
        failures.join("\n")
    );
}

/// Guard: the fixture set matches the script's expectations. Each name
/// in ALL_FIXTURES must correspond to a source example the fetch
/// script can find, so a renamed/removed Bevy example fails HERE
/// (clearly) instead of inside CI's fixture-build step (cryptically).
///
/// Generation-aware: only fixtures GENERATED on this machine (detected
/// via `src/main.rs`, which is never committed) must carry a manifest.
/// CI legs download prebuilt binaries and only have the committed
/// `tests/playtest.rs` — no generation happened there, so the guard
/// must not demand manifests from them.
#[test]
fn fixture_manifest_is_consistent() {
    let script = repo_root().join("scripts/fetch_bevy_examples.sh");
    let body = std::fs::read_to_string(&script).expect("fetch script exists");
    assert!(
        body.contains("examples/showcase"),
        "fetch script should source showcase examples"
    );

    for name in ALL_FIXTURES {
        let dir = repo_root().join("fixtures").join(name);
        if dir.join("src").join("main.rs").exists() {
            let manifest = dir.join("Cargo.toml");
            assert!(
                manifest.exists(),
                "generated fixture {name} has no Cargo.toml — regenerate"
            );
        }
    }
}
